// SPDX-License-Identifier:MIT
pragma solidity ^0.8.26;

import {IFeeController} from "./interfaces/IFeeController.sol";
import {ITokenGetter} from "./interfaces/ITokenGetter.sol";
import {IPriceOracle} from "./interfaces/IPriceOracle.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

/// @title FeeController
/// @notice Manages fee configurations and calculations for various function selectors and fee types.
/// @dev Supports minimum fee enforcement in USD, maximum fee limits, dynamic token price fetching via oracle,
///      and token resolution for fee payments using specific or global token getter contracts.
contract FeeController is Ownable, IFeeController {
    /// @notice Precision constant for fee percentage calculations (basis points - 100% = 10000).
    uint256 public constant PERCENTAGE_DIVISOR = 10000;

    // ┏━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃   State Variables    ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice The price oracle used for fetching token prices and verifying supported tokens.
    IPriceOracle private oracle;

    /// @notice Maps function selector to its fee configuration.
    mapping(bytes4 => FeeConfig) private functionFeeConfigs;

    /// @notice Maps target contract address and function selector to a token getter contract (specific).
    mapping(address => mapping(bytes4 => address)) private tokenGetters;

    /// @notice Maps function selector to a fallback token getter contract (global).
    mapping(bytes4 => address) private globalTokenGetters;

    /// @notice Maps FeeType to its maximum allowed fee percentage.
    mapping(FeeType => uint256) private maxFeeLimits;

    /// @notice Global minimum fee in USD (18 decimals)
    uint256 public minFeeInUSD;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃              Constructor            ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Initializes the FeeController contract.
    /// @param _oracle Address of the price oracle contract.
    /// @param _maxFeeLimits Array of maximum fee percentages for Deposit, Withdraw, and Reward types.
    /// @param _minFeeInUSD Global minimum fee in USD (18 decimals)
    ///
    /// @dev Example: _minFeeInUSD = 1e18 means $1 minimum for ALL fee types
    constructor(address initialOwner, address _oracle, uint256[] memory _maxFeeLimits, uint256 _minFeeInUSD)
        Ownable(initialOwner)
    {
        if (_oracle == address(0)) {
            revert ZeroAddressNotValid();
        }

        if (_maxFeeLimits.length != 3) {
            revert InvalidArrayLength();
        }

        oracle = IPriceOracle(_oracle);

        // Default max fees (basis points)
        maxFeeLimits[FeeType.Deposit] = _maxFeeLimits[0];
        maxFeeLimits[FeeType.Withdraw] = _maxFeeLimits[1];
        maxFeeLimits[FeeType.Reward] = _maxFeeLimits[2];

        // Default min fees in USD (18 decimals, e.g., 1e18 = $1)
        minFeeInUSD = _minFeeInUSD;
    }

    /// @inheritdoc IFeeController
    function setFunctionFeeConfig(bytes4 _selector, FeeType _feeType, uint256 _feePercentage) external onlyOwner {
        if (_feePercentage > maxFeeLimits[_feeType]) {
            revert FeePercentageExceedLimit();
        }

        functionFeeConfigs[_selector] = FeeConfig(_feeType, _feePercentage);

        emit FeeConfigSet(_selector, _feeType, _feePercentage);
    }

    /// @inheritdoc IFeeController
    function setTokenGetter(bytes4 _selector, address _tokenGetter, address _target) external onlyOwner {
        if (_target == address(0) || _tokenGetter == address(0)) {
            revert ZeroAddressNotValid();
        }

        tokenGetters[_target][_selector] = _tokenGetter;
        emit TokenGetterSet(_target, _selector, _tokenGetter);
    }

    /// @inheritdoc IFeeController
    function setGlobalTokenGetter(bytes4 _selector, address _tokenGetter) external onlyOwner {
        if (_tokenGetter == address(0)) {
            revert ZeroAddressNotValid();
        }

        globalTokenGetters[_selector] = _tokenGetter;
        emit GlobalTokenGetterSet(_selector, _tokenGetter);
    }

    function setMinFeeInUSD(uint256 _minFeeInUSD) external onlyOwner {
        minFeeInUSD = _minFeeInUSD;
        emit MinFeeInUSDUpdated(_minFeeInUSD);
    }

    function _getTokenDecimals(address token) internal view returns (uint8) {
        (bool success, bytes memory data) = token.staticcall(abi.encodeWithSelector(IERC20Metadata.decimals.selector));

        if (success && data.length >= 32) {
            return abi.decode(data, (uint8));
        }

        // fallback default
        return 18;
    }

    function calculateFee(address _token, bytes4 _selector, uint256 _volume) external view returns (uint256) {
        bytes32 _oracleID = oracle.oracleID(_token);
        FeeConfig memory _config = functionFeeConfigs[_selector];

        if (_oracleID == bytes32(0) || _config.feePercentage == 0) {
            return minFeeInUSD;
        }

        uint256 _tokenPrice = oracle.getTokenPrice(_token);

        uint256 _feeAmount = _volume * _config.feePercentage / PERCENTAGE_DIVISOR;

        uint8 _tokenDecimals = _getTokenDecimals(_token);

        // Normalize fee amount to 18 decimals
        uint256 _normalizedFee;
        if (_tokenDecimals == 18) {
            _normalizedFee = _feeAmount;
        } else if (_tokenDecimals < 18) {
            _normalizedFee = _feeAmount * (10 ** (18 - _tokenDecimals));
        } else {
            _normalizedFee = _feeAmount / (10 ** (_tokenDecimals - 18));
        }

        uint256 _feeInUSD = _normalizedFee * _tokenPrice / (10 ** oracle.PRICE_DECIMALS());

        return _feeInUSD < minFeeInUSD ? minFeeInUSD : _feeInUSD;
    }

    /// @inheritdoc IFeeController
    function calculateTokenAmount(address token, uint256 feeInUSD) external view returns (uint256) {
        bytes32 oracleID = oracle.oracleID(token);

        if (oracleID == bytes32(0)) {
            revert NoOracleExist();
        }

        uint256 tokenPrice = oracle.getTokenPrice(token);

        uint8 decimals = _getTokenDecimals(token);

        return tokenPrice == 0 ? 0 : (feeInUSD * (10 ** decimals)) / tokenPrice;
    }

    /// @inheritdoc IFeeController
    function getTokenForAction(address _target, bytes4 _selector, bytes memory _params)
        external
        view
        returns (address, bool)
    {
        address _tokenGetter = tokenGetter(_target, _selector);

        if (_tokenGetter == address(0)) {
            return (address(0), false);
        }

        address _token = ITokenGetter(_tokenGetter).getTokenForSelector(_selector, _params);

        return (_token, true);
    }

    /// @inheritdoc IFeeController
    function tokenGetter(address _target, bytes4 _selector) public view returns (address) {
        address _tokenGetter = tokenGetters[_target][_selector];

        if (_tokenGetter == address(0)) {
            _tokenGetter = globalTokenGetters[_selector];
        }

        return _tokenGetter;
    }

    /// @inheritdoc IFeeController
    function functionFeeConfig(bytes4 _selector) external view returns (FeeConfig memory) {
        return functionFeeConfigs[_selector];
    }

    /// @inheritdoc IFeeController
    function maxFeeLimit(FeeType _type) external view returns (uint256) {
        return maxFeeLimits[_type];
    }

    /// @inheritdoc IFeeController
    function priceOracle() external view returns (address) {
        return address(oracle);
    }

    /// @inheritdoc IFeeController
    function hasOracle(address token) external view returns (bool) {
        return oracle.oracleID(token) != bytes32(0);
    }
}

contracts/FeeHandler.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IFeeHandler} from "./interfaces/IFeeHandler.sol";
import {IFeeReduction} from "./interfaces/IFeeReduction.sol";
import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";

/// @title FeeHandler
/// @notice Handles fee distribution logic between beneficiary, creator, vault, and treasury.
/// @dev Supports both ERC20 tokens and native ETH fee handling with optional fee reduction and primary token discounts.
contract FeeHandler is Ownable, IFeeHandler {
    using SafeTransferLib for address;

    // ┏━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃   State Variables    ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━┛

    // @notice Address of the primary token for fee discounts.
    address public primaryToken;

    /// @notice Divisor for percentage calculations (10000 = 100%).
    uint256 public constant PERCENTAGE_DIVISOR = 10000;

    /// @notice Maximum discount allowed for primary token fees (50%).
    uint256 public constant MAX_PRIMARY_TOKEN_DISCOUNT = 5000;

    /// @notice Address of the vault where fees are stored.
    address public vault;

    /// @notice Address of the contract where fees are burned.
    address public burnerAddress;

    /// @notice Address of the reduction contract for user-specific fee reduction.
    address public reduction;

    /// @notice Percentage share for the fee beneficiary.
    uint256 public beneficiaryPercentage;

    /// @notice Percentage share for the fee creator.
    uint256 public creatorPercentage;

    /// @notice Percentage share for the vault.
    uint256 public vaultPercentage;

    /// @notice Discount in percentage when pay with primary token
    uint256 public primaryTokenDiscount;

    /// @notice Percentage of primary token burned.
    uint256 public primaryTokenBurn;

    /// @notice Percentage of non primary token burned.
    uint256 public tokenBurn;

    /// @notice Mapping of allowed tokens for fee payment.
    mapping(address token => bool) private allowedTokens;

    /// @notice Tracks withdrawable balances for each receiver adress and token
    mapping(address receiver => mapping(address token => uint256)) private withdrawableBalances;

    /// @notice user deposits for a token (including native ETH under address(0))
    mapping(address user => mapping(address token => uint256)) private deposits;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃              Constructor            ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @param _vault Address of the vault.
    /// @param _beneficaryPercentage Percentage share for the beneficiary.
    /// @param _creatorPercentage Percentage share for the creator.
    /// @param _vaultPercentage Percentage share for the vault.
    constructor(
        address _initialOwner,
        address _vault,
        uint256 _beneficaryPercentage,
        uint256 _creatorPercentage,
        uint256 _vaultPercentage
    ) Ownable(_initialOwner) {
        _updateVault(_vault);
        _updatePercentages(_beneficaryPercentage, _creatorPercentage, _vaultPercentage); // Default percentages: 30% beneficiary, 20% creator, 50% vault
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃      Public Functions     ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    function handleFeeWithVault(address token, uint256 amount, address beneficiary, address creator)
        external
        returns (uint256)
    {
        // check the owner of the sender contract
        address vaultOwner = Ownable(msg.sender).owner();

        (
            uint256 remaining,
            uint256 totalFee,
            uint256 beneficiaryAmount,
            uint256 creatorAmount,
            uint256 vaultAmount,
            uint256 burnAmount
        ) = _handleFee(vaultOwner, token, amount, beneficiary, creator);

        if (remaining > 0) {
            // pull remaining from sender
            token.safeTransferFrom(msg.sender, address(this), remaining);
        }

        emit FeeHandled(
            token, totalFee, beneficiary, creator, beneficiaryAmount, creatorAmount, vaultAmount, burnAmount
        );

        return totalFee + burnAmount;
    }

    function handleFeeWithVaultETH(uint256 amount, address beneficiary, address creator)
        external
        payable
        returns (uint256)
    {
        // check the owner of the sender contract
        address vaultOwner = Ownable(msg.sender).owner();

        (
            uint256 remaining,
            uint256 totalFee,
            uint256 beneficiaryAmount,
            uint256 creatorAmount,
            uint256 vaultAmount,
            uint256 burnAmount
        ) = _handleFee(vaultOwner, address(0), amount, beneficiary, creator);

        // then accept msg.value for the remainder
        if (remaining > 0) {
            if (msg.value < remaining) revert InvalidAmount(); // or custom error InsufficientPayment()
            // if msg.value > remaining, refund excess
            uint256 excess = msg.value - remaining;
            if (excess > 0) {
                // refund extra
                msg.sender.safeTransferETH(excess);
            }
        } else {
            // user sent ETH but deposit fully covered fee: refund entire msg.value
            if (msg.value > 0) {
                msg.sender.safeTransferETH(msg.value);
            }
        }

        emit FeeHandledETH(totalFee, beneficiary, creator, beneficiaryAmount, creatorAmount, vaultAmount, burnAmount);

        return totalFee + burnAmount;
    }

    /// @inheritdoc IFeeHandler
    function handleFee(address token, uint256 amount, address beneficiary, address creator)
        external
        returns (uint256)
    {
        (
            uint256 remaining,
            uint256 totalFee,
            uint256 beneficiaryAmount,
            uint256 creatorAmount,
            uint256 vaultAmount,
            uint256 burnAmount
        ) = _handleFee(msg.sender, token, amount, beneficiary, creator);

        if (remaining > 0) {
            // pull remaining from sender
            token.safeTransferFrom(msg.sender, address(this), remaining);
        }

        emit FeeHandled(
            token, totalFee, beneficiary, creator, beneficiaryAmount, creatorAmount, vaultAmount, burnAmount
        );

        return totalFee + burnAmount;
    }

    /// @inheritdoc IFeeHandler
    function handleFeeETH(address beneficiary, address creator, uint256 amount) external payable returns (uint256) {
        (
            uint256 remaining,
            uint256 totalFee,
            uint256 beneficiaryAmount,
            uint256 creatorAmount,
            uint256 vaultAmount,
            uint256 burnAmount
        ) = _handleFee(msg.sender, address(0), amount, beneficiary, creator);

        // then accept msg.value for the remainder
        if (remaining > 0) {
            if (msg.value < remaining) revert InvalidAmount(); // or custom error InsufficientPayment()
            // if msg.value > remaining, refund excess
            uint256 excess = msg.value - remaining;
            if (excess > 0) {
                // refund extra
                msg.sender.safeTransferETH(excess);
            }
        } else {
            // user sent ETH but deposit fully covered fee: refund entire msg.value
            if (msg.value > 0) {
                msg.sender.safeTransferETH(msg.value);
            }
        }

        emit FeeHandledETH(totalFee, beneficiary, creator, beneficiaryAmount, creatorAmount, vaultAmount, burnAmount);

        return totalFee + burnAmount;
    }

    /// @inheritdoc IFeeHandler
    function withdraw(address token) external {
        uint256 amount = withdrawableBalances[msg.sender][token];
        if (amount == 0) revert InvalidAmount();
        withdrawableBalances[msg.sender][token] = 0;

        if (token == address(0)) {
            msg.sender.safeTransferETH(amount);
        } else {
            token.safeTransfer(msg.sender, amount);
        }

        emit Withdrawn(msg.sender, token, amount);
    }

    /// @inheritdoc IFeeHandler
    function activatePrimaryToken(
        address _token,
        address _burnerAddress,
        uint256 _primaryTokenDiscount,
        uint256 _primaryTokenBurn,
        uint256 _tokenBurn
    ) external onlyOwner {
        if (primaryTokenActive()) revert PrimaryTokenAlreadyActivated();
        _validateAddress(_token);
        _validateAddress(_burnerAddress);

        _validatePercentage(_primaryTokenBurn);
        _validatePercentage(_tokenBurn);
        _validatePercentage(_primaryTokenDiscount);
        if (_primaryTokenDiscount > MAX_PRIMARY_TOKEN_DISCOUNT) revert InvalidPercentage();

        primaryToken = _token;
        burnerAddress = _burnerAddress;

        primaryTokenDiscount = _primaryTokenDiscount;
        primaryTokenBurn = _primaryTokenBurn;
        tokenBurn = _tokenBurn;

        emit PrimaryTokenActivated(_token, _burnerAddress, _primaryTokenBurn, _tokenBurn);
    }

    /// @inheritdoc IFeeHandler
    function updateVault(address _vault) external onlyOwner {
        _updateVault(_vault);
    }

    /// @inheritdoc IFeeHandler
    function updateReduction(address _reduction) external onlyOwner {
        _validateAddress(_reduction);
        reduction = _reduction;
        emit UpdatedReduction(_reduction);
    }

    function updateBurnerAddress(address _burnerAddress) external onlyOwner {
        _updateBurnerAddress(_burnerAddress);
    }

    /// @inheritdoc IFeeHandler
    function updatePercentages(uint256 _beneficiary, uint256 _creator, uint256 _vault) external onlyOwner {
        _updatePercentages(_beneficiary, _creator, _vault);
    }

    /// @inheritdoc IFeeHandler
    function updateTokenAllowance(address token, bool allowed) external onlyOwner {
        allowedTokens[token] = allowed;

        emit UpdatedTokenAllowance(token, allowed);
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    Account Functions     ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Deposit ERC20 tokens to be used for future fees
    function depositToken(address token, uint256 amount) external {
        _validateAmount(amount);
        if (!allowedTokens[token]) revert TokenNotAllowed();

        // transfer tokens from user into contract
        token.safeTransferFrom(msg.sender, address(this), amount);

        deposits[msg.sender][token] += amount;
        emit Deposit(msg.sender, token, amount);
    }

    function depositTokenFor(address to, address token, uint256 amount) external {
        _validateAmount(amount);
        if (!allowedTokens[token]) revert TokenNotAllowed();

        // transfer tokens from user into contract
        token.safeTransferFrom(msg.sender, address(this), amount);

        deposits[to][token] += amount;
        emit Deposit(to, token, amount);
    }

    /// @notice Withdraw part or full of user's deposit for a token
    function withdrawDeposit(address token, uint256 amount) external {
        uint256 balance = deposits[msg.sender][token];
        if (amount == 0 || amount > balance) revert InvalidAmount();

        deposits[msg.sender][token] = balance - amount;

        if (token == address(0)) {
            msg.sender.safeTransferETH(amount);
        } else {
            token.safeTransfer(msg.sender, amount);
        }
        emit DepositWithdrawn(msg.sender, token, amount);
    }

    /// @notice Deposit native ETH to be used for future fees
    function depositETH() external payable {
        if (!allowedTokens[address(0)]) revert TokenNotAllowed();
        _validateAmount(msg.value);
        deposits[msg.sender][address(0)] += msg.value;
        emit Deposit(msg.sender, address(0), msg.value);
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    Internal Functions     ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    function _handleFee(address feePayer, address token, uint256 amount, address beneficiary, address creator)
        internal
        returns (
            uint256 remaining,
            uint256 totalFee,
            uint256 beneficiaryAmount,
            uint256 creatorAmount,
            uint256 vaultAmount,
            uint256 burnAmount
        )
    {
        _validateAmount(amount);
        _validateBeneficiary(beneficiary);

        if (!allowedTokens[token]) {
            revert TokenNotAllowed();
        }

        (totalFee, burnAmount) = _feeCalculation(amount, token);

        (beneficiaryAmount, creatorAmount, vaultAmount) = _tokenDistribution(totalFee);

        withdrawableBalances[beneficiary][token] += beneficiaryAmount;

        if (creator != address(0)) {
            withdrawableBalances[creator][token] += creatorAmount;
            withdrawableBalances[vault][token] += vaultAmount;
        } else {
            withdrawableBalances[vault][token] += vaultAmount + creatorAmount;
        }

        if (burnAmount > 0) {
            withdrawableBalances[burnerAddress][token] += burnAmount;
        }

        // Collect total funds from sender
        uint256 requiredAmount = totalFee + burnAmount;

        remaining = requiredAmount;

        //Check if there is the primary token deposited

        uint256 depositAvailable = deposits[feePayer][token];
        if (depositAvailable > 0) {
            if (depositAvailable >= remaining) {
                deposits[feePayer][token] = depositAvailable - remaining;
                remaining = 0;
            } else {
                // use all deposit
                remaining -= depositAvailable;
                deposits[feePayer][token] = 0;
            }
        }
    }

    function _updateVault(address _vault) internal {
        _validateAddress(_vault);
        vault = _vault;
        emit UpdatedVault(_vault);
    }

    function _updateBurnerAddress(address _burnerAddress) internal {
        _validateAddress(_burnerAddress);
        burnerAddress = _burnerAddress;
        emit UpdatedBurnerAddress(_burnerAddress);
    }

    function _updatePercentages(uint256 _beneficiary, uint256 _creator, uint256 _vault) internal {
        if (_beneficiary + _creator + _vault != PERCENTAGE_DIVISOR) revert InvalidPercentageDistribution();
        beneficiaryPercentage = _beneficiary;
        creatorPercentage = _creator;
        vaultPercentage = _vault;
        emit UpdatedPercentages(_beneficiary, _creator, _vault);
    }

    function _tokenDistribution(uint256 amount)
        internal
        view
        returns (uint256 beneficiaryAmount, uint256 creatorAmount, uint256 vaultAmount)
    {
        beneficiaryAmount = (amount * beneficiaryPercentage) / PERCENTAGE_DIVISOR;
        creatorAmount = (amount * creatorPercentage) / PERCENTAGE_DIVISOR;
        vaultAmount = amount - beneficiaryAmount - creatorAmount;
    }

    function _feeCalculation(uint256 amount, address token)
        internal
        view
        returns (uint256 totalFee, uint256 burnAmount)
    {
        totalFee = amount;

        if (reduction != address(0)) {
            uint256 reductionPercentage = IFeeReduction(reduction).getFeeReduction(msg.sender);
            totalFee = totalFee - totalFee * reductionPercentage / PERCENTAGE_DIVISOR;
        }

        //The amount of burn varies if the primary token is used or not. If no primary token is activated, no tokens will be burned.
        if (primaryTokenActive()) {
            if (token == primaryToken) {
                totalFee = totalFee - totalFee * primaryTokenDiscount / PERCENTAGE_DIVISOR;
            }
            burnAmount = token == primaryToken
                ? (totalFee * primaryTokenBurn) / PERCENTAGE_DIVISOR
                : (totalFee * tokenBurn) / PERCENTAGE_DIVISOR;
            totalFee -= burnAmount;
        }
    }

    function _validateAddress(address _addr) internal pure {
        if (_addr == address(0)) {
            revert ZeroAddressNotValid();
        }
    }

    function _validateAmount(uint256 amount) internal pure {
        if (amount == 0) revert InvalidAmount();
    }

    function _validateBeneficiary(address beneficiary) internal pure {
        if (beneficiary == address(0)) revert InvalidBeneficiary();
    }

    function _validatePercentage(uint256 percentage) internal pure {
        if (percentage > PERCENTAGE_DIVISOR || percentage == 0) revert InvalidPercentage();
    }

    // ┏━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    View Functions     ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @inheritdoc IFeeHandler
    function primaryTokenActive() public view returns (bool) {
        return primaryToken != address(0);
    }

    /// @inheritdoc IFeeHandler
    function tokenAllowed(address token) external view returns (bool) {
        return allowedTokens[token];
    }

    /// @inheritdoc IFeeHandler
    function getWithdrawableBalance(address user, address token) external view returns (uint256 balance) {
        return withdrawableBalances[user][token];
    }

    /// @notice Get deposit balance for user / token
    function getDeposit(address user, address token) external view returns (uint256) {
        return deposits[user][token];
    }
}

