// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @title IActionRegistry
/// @notice Interface for managing and validating allowed action contract addresses.
/// @dev Used to whitelist and check access for external action contracts.
interface IActionRegistry {
    // ┏━━━━━━━━━━━━━━━━━┓
    // ┃    Errors       ┃
    // ┗━━━━━━━━━━━━━━━━━┛

    error ZeroAddressNotValid();
    error ActionNotRegistered();

    // ┏━━━━━━━━━━━━━━━━━━┓
    // ┃     Events       ┃
    // ┗━━━━━━━━━━━━━━━━━━┛

    event ActionAllowed(address indexed action);
    event ActionRevoked(address indexed action);

    // ┏━━━━━━━━━━━━━━━━━━┓
    // ┃   Functions      ┃
    // ┗━━━━━━━━━━━━━━━━━━┛

    /// @notice Allows (whitelists) an action contract address.
    /// @dev Only callable by the owner or authorized entity.
    /// @param action The address of the action contract to allow.
    function allowAction(address action) external;

    /// @notice Revokes a previously allowed action contract address.
    /// @dev Only callable by the owner or authorized entity.
    /// @param action The address of the action contract to revoke.
    function revokeAction(address action) external;

    /// @notice Checks whether a given action contract address is allowed.
    /// @param action The address to check.
    /// @return allowed A boolean indicating whether the action is allowed.
    function isAllowed(address action) external view returns (bool);
}

contracts/interfaces/ICondition.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";

interface ICondition is IERC165 {
    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    Execution functions    ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Updates a condition. To be overridden in derived contracts.
    /// @param id The condition ID.
    /// @return success Whether the update was performed.
    function updateCondition(uint32 id) external returns (bool);

    /// @notice Deletes a condition if it's not in use.
    /// @param id The condition ID to delete.
    function deleteCondition(uint32 id) external;

    /// @notice Associates an automation with a condition.
    /// @param id The condition ID.
    /// @param automation The automation ID.
    /// @return success Whether the automation was added.
    function addAutomationToCondition(uint32 id, uint32 automation) external returns (bool);

    /// @notice Associates a strategy with a condition.
    /// @param id The condition ID.
    /// @param strategy The strategy ID.
    /// @return success Whether the strategy was added.
    function addStrategyToCondition(uint32 id, uint32 strategy) external returns (bool);

    /// @notice Removes an automation from a condition.
    /// @param id The condition ID.
    /// @param automation The automation ID.
    /// @return success Whether the automation was removed.
    function removeAutomationFromCondition(uint32 id, uint32 automation) external returns (bool);

    /// @notice Removes a strategy from a condition.
    /// @param id The condition ID.
    /// @param strategy The strategy ID.
    /// @return success Whether the strategy was removed.
    function removeStrategyFromCondition(uint32 id, uint32 strategy) external returns (bool);

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃    External View Functions       ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Returns whether a condition is active.
    /// @param wallet The wallet address.
    /// @param id The condition ID.
    /// @return active Whether the condition is active.
    function isConditionActive(address wallet, uint32 id) external view returns (bool);

    /// @notice Gets strategies associated with a condition.
    /// @param wallet The wallet address.
    /// @param id The condition ID.
    /// @return strategyList List of strategy IDs.
    function strategies(address wallet, uint32 id) external view returns (uint32[] memory);

    /// @notice Gets automations associated with a condition.
    /// @param wallet The wallet address.
    /// @param id The condition ID.
    /// @return automationList List of automation IDs.
    function automations(address wallet, uint32 id) external view returns (uint32[] memory);

    /// @notice Checks the condition logic. Meant to be overridden.
    /// @param wallet Wallet that owns the condition.
    /// @param id Condition ID.
    /// @return status The result of the condition check.
    function checkCondition(address wallet, uint32 id) external view returns (uint8);

    /// @notice Indicates whether the condition is updatable. Meant to be overridden.
    /// @param wallet Wallet address.
    /// @param id Condition ID.
    /// @return updateable True if the condition is updatable.
    function isUpdateable(address wallet, uint32 id) external view returns (bool);

    /// @notice Checks whether a condition includes a specific automation.
    /// @param wallet Wallet address.
    /// @param id Condition ID.
    /// @param automationId Automation ID.
    /// @return inCondition True if the condition includes the automation.
    function conditionInAutomation(address wallet, uint32 id, uint32 automationId) external view returns (bool);

    /// @notice Checks whether a condition includes a specific strategy.
    /// @param wallet Wallet address.
    /// @param id Condition ID.
    /// @param strategyId Strategy ID.
    /// @return inCondition True if the condition includes the strategy.
    function conditionInStrategy(address wallet, uint32 id, uint32 strategyId) external view returns (bool);
}

contracts/interfaces/IFeeController.sol.content:
// SPDX-License-Identifier:MIT
pragma solidity ^0.8.26;

interface IFeeController {
    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃     Structs / Enums       ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Enum representing the type of fee.
    enum FeeType {
        Deposit,
        Withdraw,
        Reward
    }

    /// @notice Struct containing fee configuration parameters.
    /// @param feeType The type of fee being applied.
    /// @param feePercentage The fee percentage in basis points (1% = 100).
    struct FeeConfig {
        FeeType feeType;
        uint256 feePercentage;
    }

    // ┏━━━━━━━━━━━━━━━━━┓
    // ┃    Errors       ┃
    // ┗━━━━━━━━━━━━━━━━━┛

    /// @notice Thrown when the specified fee percentage exceeds the allowed maximum limit.
    error FeePercentageExceedLimit();

    /// @notice Thrown when a provided address is the zero address.
    error ZeroAddressNotValid();

    /// @notice Thrown when no oracle exists for the specified token.
    error NoOracleExist();

    /// @notice Thrown when an array length is invalid or does not match the expected length.
    error InvalidArrayLength();

    // ┏━━━━━━━━━━━━━━━━━━┓
    // ┃     Events       ┃
    // ┗━━━━━━━━━━━━━━━━━━┛

    /// @notice Emitted when a new fee configuration is set for a function selector.
    /// @param selector The function selector.
    /// @param feeType The type of fee applied.
    /// @param feePercentage The fee percentage in basis points.
    event FeeConfigSet(bytes4 indexed selector, FeeType feeType, uint256 feePercentage);

    /// @notice Emitted when a token getter contract is set for a target contract and function selector.
    /// @param target The target contract address.
    /// @param selector The function selector.
    /// @param tokenGetter The address of the token getter contract.
    event TokenGetterSet(address indexed target, bytes4 indexed selector, address tokenGetter);

    /// @notice Emitted when a global fallback token getter is set for a function selector.
    /// @param selector The function selector.
    /// @param tokenGetter The address of the global token getter contract.
    event GlobalTokenGetterSet(bytes4 indexed selector, address tokenGetter);

    /// @notice Emitted when a minimum fee amount in USD is set for a specific fee type.
    /// @param feeType The fee type.
    /// @param minFeeUSD The minimum fee amount in USD (18 decimals).
    event MinFeeSet(FeeType feeType, uint256 minFeeUSD);

    event MinFeeInUSDUpdated(uint256 minFeeInUSD);

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃            Admin Functions          ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Sets the fee configuration for a specific function selector.
    /// @param selector Function selector to configure the fee for.
    /// @param feeType Type of fee (Deposit, Withdraw, Reward).
    /// @param feePercentage Fee percentage in basis points (max 10000).
    function setFunctionFeeConfig(bytes4 selector, FeeType feeType, uint256 feePercentage) external;

    /// @notice Sets a token getter contract for a specific target contract and function selector.
    /// @param selector Function selector for which the token getter is set.
    /// @param tokenGetter Address of the token getter contract.
    /// @param target Target contract address where the selector is used.
    function setTokenGetter(bytes4 selector, address tokenGetter, address target) external;

    /// @notice Sets a global fallback token getter contract for a specific function selector.
    /// @param selector Function selector for which the global token getter is set.
    /// @param tokenGetter Address of the token getter contract.
    function setGlobalTokenGetter(bytes4 selector, address tokenGetter) external;

    function setMinFeeInUSD(uint256 _minFeeInUSD) external;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃          View / Utility             ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Retrieves the token address associated with a function call on a target contract.
    /// @dev Uses a specific token getter if available, otherwise falls back to a global one.
    /// @param target Target contract address.
    /// @param selector Function selector of the target function.
    /// @param params Encoded parameters for the token getter to use.
    /// @return token Address of the token used for fee payment.
    /// @return exists Boolean indicating if a token getter was found.
    function getTokenForAction(address target, bytes4 selector, bytes memory params)
        external
        view
        returns (address, bool);

    /// @notice Calculates the applicable fee amount for a given token, function selector, and volume.
    /// @dev Returns the higher of the calculated fee or the configured minimum fee in USD.
    /// @param token Address of the token being charged.
    /// @param selector Function selector for which the fee is being calculated.
    /// @param volume Transaction volume (usually token amount).
    /// @return The applicable fee amount denominated in USD (18 decimals).
    function calculateFee(address token, bytes4 selector, uint256 volume) external view returns (uint256);

    /// @notice Converts a fee denominated in USD to its equivalent token amount.
    /// @param token Address of the token.
    /// @param feeInUSD Fee amount in USD (18 decimals).
    /// @return Equivalent token amount based on the oracle price.
    function calculateTokenAmount(address token, uint256 feeInUSD) external view returns (uint256);

    /// @notice Returns the address of the token getter contract used for a specific target and selector.
    /// @param target Target contract address.
    /// @param selector Function selector.
    /// @return Address of the token getter contract (or zero address if none found).
    function tokenGetter(address target, bytes4 selector) external view returns (address);

    /// @notice Returns the fee configuration for a given function selector.
    /// @param selector Function selector.
    /// @return The FeeConfig struct associated with the selector.
    function functionFeeConfig(bytes4 selector) external view returns (FeeConfig memory);

    /// @notice Returns the maximum allowed fee percentage for a specific FeeType.
    /// @param feeType FeeType enum value.
    /// @return Maximum fee percentage allowed.
    function maxFeeLimit(FeeType feeType) external view returns (uint256);

    /// @notice Returns the minimum fee amount in USD.
    /// @return Minimum fee in USD (18 decimals).
    function minFeeInUSD() external view returns (uint256);

    /// @notice Checks if a given token has an associated price oracle.
    /// @param token Address of the token.
    /// @return Boolean indicating if an oracle exists for the token.
    function hasOracle(address token) external view returns (bool);

    /// @notice Returns the address of the configured price oracle.
    /// @return Address of the oracle contract.
    function priceOracle() external view returns (address);
}

contracts/interfaces/IFeeHandler.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

interface IFeeHandler {
    // ┏━━━━━━━━━━━━━━━━━┓
    // ┃    Errors       ┃
    // ┗━━━━━━━━━━━━━━━━━┛

    error InvalidAmount();
    error ZeroAddressNotValid();
    error InvalidBeneficiary();
    error PrimaryTokenAlreadyActivated();
    error InvalidPercentageDistribution();
    error TokenNotAllowed();
    error InvalidPercentage();

    // ┏━━━━━━━━━━━━━━━━━━┓
    // ┃     Events       ┃
    // ┗━━━━━━━━━━━━━━━━━━┛

    event FeeHandled(
        address indexed token,
        uint256 totalFee,
        address beneficiary,
        address creator,
        uint256 beneficiaryFee,
        uint256 creatorFee,
        uint256 vaultFee,
        uint256 burnAmount
    );
    event FeeHandledETH(
        uint256 totalFee,
        address beneficiary,
        address creator,
        uint256 beneficiaryFee,
        uint256 creatorFee,
        uint256 vaultFee,
        uint256 burnAmount
    );
    event PrimaryTokenActivated(address token, address treasury, uint256 primaryTokenBurn, uint256 tokenBurn);
    event UpdatedVault(address vault);
    event UpdatedBurnerAddress(address burnerAddress);
    event UpdatedPercentages(uint256 beneficiary, uint256 creator, uint256 vault);
    event UpdatedTokenAllowance(address token, bool allowed);
    event UpdatedReduction(address reduction);
    event Withdrawn(address indexed receiver, address indexed token, uint256 amount);
    event Deposit(address indexed user, address indexed token, uint256 amount);
    event DepositWithdrawn(address indexed user, address indexed token, uint256 amount);

    /// @notice Handles ERC20 fee payment. Stores receivable amounts for beneficiary, creator, and vault.
    /// @param token The token address used for payment.
    /// @param amount The total fee amount sent by the user.
    /// @param beneficiary The fee beneficiary address.
    /// @param creator Optional creator address to receive part of the fee.
    /// @return totalAmount Total fee + burn amount recorded.
    function handleFee(address token, uint256 amount, address beneficiary, address creator)
        external
        returns (uint256);

    /// @notice Handles native ETH fee payment. Stores receivable ETH for withdrawal.
    /// @param beneficiary The fee beneficiary address.
    /// @param creator Optional creator address.
    /// @return totalAmount Total fee + burn amount recorded.
    /// @param amount The total fee amount sent by the user.
    function handleFeeETH(address beneficiary, address creator, uint256 amount) external payable returns (uint256);

    function handleFeeWithVault(address token, uint256 amount, address beneficiary, address creator)
        external
        returns (uint256);

    function handleFeeWithVaultETH(uint256 amount, address beneficiary, address creator)
        external
        payable
        returns (uint256);

    /// @notice Allows a user to withdraw their accumulated fee balance for a given token.
    /// @param token The token address to withdraw (use address(0) for ETH).
    function withdraw(address token) external;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃            Admin Functions          ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Activates primary token for fee discounts.
    /// @param token Address of the primary token.
    /// @param treasury Address of the treasury.
    /// @param primaryTokenBurn The percenetage of primary token discount.
    /// @param primaryTokenBurn The percenetage of primary token burned.
    /// @param tokenBurn The percentage of token burned.
    function activatePrimaryToken(
        address token,
        address treasury,
        uint256 primaryTokenDiscount,
        uint256 primaryTokenBurn,
        uint256 tokenBurn
    ) external;

    function primaryToken() external returns (address);

    /// @notice Updates vault address.
    /// @param vault New vault address.
    function updateVault(address vault) external;

    /// @notice Updates reduction contract address.
    /// @param reduction New reduction contract address.
    function updateReduction(address reduction) external;

    /// @notice Updates fee distribution percentages.
    /// @param beneficiary Beneficiary percentage.
    /// @param creator Creator percentage.
    /// @param vault Vault percentage.
    function updatePercentages(uint256 beneficiary, uint256 creator, uint256 vault) external;

    /// @notice Updates token allowance for fee payment.
    /// @param token Token address.
    /// @param allowed Boolean indicating if the token is allowed.
    function updateTokenAllowance(address token, bool allowed) external;

    // ┏━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┓
    // ┃          View / Utility             ┃
    // ┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛

    /// @notice Returns true if a primary token is active.
    /// @return active Boolean indicating if primary token is active.
    function primaryTokenActive() external view returns (bool);

    /// @notice Returns true if a token is allowed for payment.
    /// @param token Token address.
    /// @return allowed Boolean indicating if token is allowed.
    function tokenAllowed(address token) external view returns (bool);

    /// @notice Returns the withdrawable balance for a given user and token.
    /// @param user The address of the user.
    /// @param token The token address (use address(0) for ETH).
    /// @return balance The amount the user can withdraw.
    function getWithdrawableBalance(address user, address token) external view returns (uint256 balance);

    function getDeposit(address user, address token) external view returns (uint256);
}

